import sys
from collections import defaultdict, deque

def find_centroid(tree, size, node, parent):
    largest_subtree = 0
    centroid = node
    for neighbor in tree[node]:
        if neighbor != parent and size[neighbor] > largest_subtree:
            largest_subtree = size[neighbor]
            centroid = neighbor
    return centroid if largest_subtree <= size[node] // 2 else find_centroid(tree, size, parent, -1)

def dfs(tree, node, parent, depth, depths, sizes):
    depths[node] = depth
    sizes[node] = 1
    for neighbor in tree[node]:
        if neighbor != parent:
            dfs(tree, neighbor, node, depth + 1, depths, sizes)
            sizes[node] += sizes[neighbor]

def solve(tree, n):
    depths = [0] * (n + 1)
    sizes = [0] * (n + 1)
    dfs(tree, 1, -1, 0, depths, sizes)

    centroid = find_centroid(tree, sizes, 1, -1)

    max_edges = 0
    best_triplet = (0, 0, 0)

    for neighbor in tree[centroid]:
        sub_tree_sizes = [0] * (n + 1)
        sub_tree_depths = [0] * (n + 1)
        dfs(tree, neighbor, centroid, 0, sub_tree_depths, sub_tree_sizes)

        for other_neighbor in tree[centroid]:
            if other_neighbor != neighbor:
                for leaf in tree[other_neighbor]:
                    if leaf != centroid:
                        edges_covered = sizes[leaf] + sizes[neighbor] + sizes[other_neighbor] - 3
                        if edges_covered > max_edges:
                            max_edges = edges_covered
                            best_triplet = (leaf, neighbor, other_neighbor)

    return max_edges, best_triplet

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    tree = defaultdict(list)

    index = 1
    for _ in range(n - 1):
        a = int(data[index])
        b = int(data[index + 1])
        tree[a].append(b)
        tree[b].append(a)
        index += 2

    res, (a, b, c) = solve(tree, n)
    print(res)
    print(a, b, c)

if __name__ == "__main__":
    main()
